/**
 * Authentication settings page - configure auth providers with tabs
 */
import { useState, useEffect, useMemo } from 'react';
import { LoadingSpinner } from '../../shared/LoadingSpinner';
import { ErrorMessage } from '../../shared/ErrorMessage';
import { useSettingsAutosave } from '../../../hooks/useSettingsAutosave';
import { SettingsSection } from './settingsInputs';
import { AutosaveStatus } from './AutosaveStatus';
import { SsoProvidersSettings } from './SsoProvidersSettings';
import { SocialButtonOrderSettings } from './SocialButtonOrderSettings';

type AuthTab = 'email' | 'google' | 'apple' | 'solana' | 'passkeys' | 'instantlink' | 'sso' | 'buttonorder' | 'postlogin';

interface TabConfig {
  id: AuthTab;
  label: string;
  /** Categories to pull settings from (not used for 'sso' tab) */
  categories: string[];
  /** Optional list of specific keys to show (if omitted, show all in categories) */
  keys?: string[];
  /** If true, renders a custom component instead of settings section */
  isCustom?: boolean;
}

const TABS: TabConfig[] = [
  { id: 'email', label: 'Email', categories: ['auth.email'],
    keys: ['auth_email_enabled', 'auth_email_require_verification', 'auth_email_block_disposable'] },
  { id: 'google', label: 'Google', categories: ['auth.google'],
    keys: ['auth_google_enabled', 'auth_google_client_id'] },
  { id: 'apple', label: 'Apple', categories: ['auth.apple'],
    keys: ['auth_apple_enabled', 'auth_apple_client_id', 'auth_apple_team_id'] },
  { id: 'solana', label: 'Solana', categories: ['auth.solana'],
    keys: ['auth_solana_enabled', 'auth_solana_challenge_expiry'] },
  { id: 'passkeys', label: 'Passkeys', categories: ['auth.webauthn'],
    keys: ['auth_webauthn_enabled', 'auth_webauthn_rp_id', 'auth_webauthn_rp_name', 'auth_webauthn_rp_origin'] },
  { id: 'instantlink', label: 'Instant Link', categories: ['auth.instantlink'],
    keys: ['auth_instantlink_enabled', 'auth_instantlink_expiry', 'auth_instantlink_rate_limit'] },
  { id: 'sso', label: 'SSO Providers', categories: [], isCustom: true },
  { id: 'buttonorder', label: 'Button Order', categories: [], isCustom: true },
  { id: 'postlogin', label: 'Post-Login', categories: ['postlogin', 'postlogin.welcome', 'postlogin.complete'],
    keys: ['postlogin_redirect_url', 'postlogin_welcome_enabled', 'postlogin_welcome_route', 'postlogin_complete_enabled'] },
];

export interface AuthenticationSettingsProps {
  className?: string;
}

export function AuthenticationSettings({ className }: AuthenticationSettingsProps) {
  const {
    settings,
    edits,
    isLoading,
    autosaveStatus,
    autosaveError,
    error,
    fetchSettings,
    handleChange,
  } = useSettingsAutosave();

  const [activeTab, setActiveTab] = useState<AuthTab>('email');

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  // Get current tab config
  const currentTab = TABS.find((t) => t.id === activeTab);

  // Collect settings from all categories for the current tab
  const allTabSettings = useMemo(() => {
    if (!currentTab) return [];
    const allSettings: (typeof settings)[string] = [];
    for (const category of currentTab.categories) {
      const categorySettings = settings[category] ?? [];
      allSettings.push(...categorySettings);
    }
    return allSettings;
  }, [settings, currentTab]);

  const currentSettings = useMemo(() => {
    if (!currentTab?.keys) return allTabSettings;
    // Filter and sort by keys order
    return allTabSettings
      .filter((s) => currentTab.keys!.includes(s.key))
      .sort((a, b) => currentTab.keys!.indexOf(a.key) - currentTab.keys!.indexOf(b.key));
  }, [allTabSettings, currentTab]);

  if (isLoading && Object.keys(settings).length === 0) {
    return (
      <div className={`cedros-system-settings cedros-system-settings-loading ${className ?? ''}`}>
        <LoadingSpinner />
        <span>Loading settings...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`cedros-system-settings ${className ?? ''}`}>
        <ErrorMessage error={error.message} />
      </div>
    );
  }

  return (
    <div className={`cedros-system-settings ${className ?? ''}`}>
      <div className="cedros-settings-page-header">
        <div className="cedros-settings-page-header-content">
          <h2 className="cedros-settings-page-title">Authentication</h2>
          <p className="cedros-settings-page-description">
            Configure authentication providers and methods for user sign-in.
          </p>
        </div>
        <AutosaveStatus status={autosaveStatus} error={autosaveError} />
      </div>

      {/* Tabs */}
      <div className="cedros-admin-tabs cedros-admin-tabs--line">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            type="button"
            className={`cedros-admin-tab ${activeTab === tab.id ? 'cedros-admin-tab-active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
            aria-selected={activeTab === tab.id}
            role="tab"
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab content */}
      <div className="cedros-admin-tab-content" role="tabpanel">
        {currentTab?.id === 'buttonorder' ? (
          <SocialButtonOrderSettings settings={settings} handleChange={handleChange} />
        ) : currentTab?.isCustom ? (
          <SsoProvidersSettings />
        ) : currentSettings.length === 0 ? (
          <div className="cedros-system-settings-empty">
            <p>No settings found for {currentTab?.label ?? 'this provider'}.</p>
          </div>
        ) : (
          <SettingsSection settings={currentSettings} edits={edits} onChange={handleChange} />
        )}
      </div>
    </div>
  );
}
